DECLARE o finance_document_observations%ROWTYPE;candidate jsonb;current_snapshot jsonb;stored_snapshot jsonb;
 source_row jsonb;source_refs text[];observation jsonb;sources jsonb;public_result jsonb;
BEGIN
 SELECT * INTO o FROM finance_document_observations WHERE observation_id=p_observation;
 IF NOT FOUND THEN RAISE EXCEPTION ''Current observation reference unavailable'' USING ERRCODE=''55000'';END IF;
 -- Validate the immutable source of the compatibility anchor before using it.
 PERFORM finance_document_assert_request(o.request_id);
 candidate:=finance_document_candidate(o.subject_id,p_review_revision,o.source_kind,o.source_id);
 IF candidate->>''canRegister'' IS DISTINCT FROM ''true'' THEN RETURN candidate;END IF;
 -- Match the collector''s purchase kind after ordinary ASCII trimming. A second
 -- registry ID with the same valid card token is still the same approval base.
 IF o.source_kind=''card'' THEN
  SELECT to_jsonb(t) INTO source_row FROM card_transactions t WHERE card_txn_id=o.source_id;
  source_refs:=finance_same_card_base_refs_v1(source_row);
  IF cardinality(source_refs)<>1 OR source_refs[1] IS DISTINCT FROM o.source_id THEN
   candidate:=jsonb_set(candidate,''{canRegister}'',''false''::jsonb,false);
   candidate:=jsonb_set(candidate,''{issues}'',candidate->''issues''||finance_document_issue(''card_base_identity_conflict'',''같은 승인 기본키의 복수 원천을 확인하세요.''),false);
   public_result:=candidate-ARRAY[''previewHash'',''_safeSnapshot'',''_descriptor'',''_baseDescriptor''];
   RETURN jsonb_set(candidate,''{previewHash}'',to_jsonb(finance_document_hash(public_result)),false);
  END IF;
 END IF;
 current_snapshot:=candidate->''_safeSnapshot'';stored_snapshot:=o.safe_snapshot_json;
 IF candidate->>''documentId'' IS DISTINCT FROM o.document_id
  OR candidate->>''reviewRevisionId'' IS DISTINCT FROM o.review_revision_id
  OR candidate->>''subjectId'' IS DISTINCT FROM o.subject_id
  OR finance_same_observation_projection_v1(current_snapshot) IS DISTINCT FROM finance_same_observation_projection_v1(stored_snapshot)
 THEN RETURN candidate;END IF;
 -- Only the operational observationState may differ. Preserve the historical
 -- side snapshot and recreate its dependent public hashes with the CURRENT
 -- version/identity/eligibility. This keeps old same/group/E proofs byte equal.
 IF current_snapshot IS NOT DISTINCT FROM stored_snapshot THEN RETURN candidate;END IF;
 SELECT jsonb_agg(jsonb_build_object(''kind'',s->>''kind'',''id'',s->>''id'',''sourceHash'',finance_document_hash(s)) ORDER BY source_ordinal)
  INTO sources FROM jsonb_array_elements(stored_snapshot->''sourceSnapshots'') WITH ORDINALITY AS source_rows(s,source_ordinal);
 observation:=candidate->''observation'';
 observation:=jsonb_set(observation,''{sources}'',sources,false);
 observation:=jsonb_set(observation,''{snapshotHash}'',to_jsonb(finance_document_hash(stored_snapshot)),false);
 candidate:=jsonb_set(candidate,''{observation}'',observation,false);
 candidate:=jsonb_set(candidate,''{_safeSnapshot}'',stored_snapshot,false);
 public_result:=candidate-ARRAY[''previewHash'',''_safeSnapshot'',''_descriptor'',''_baseDescriptor''];
 RETURN jsonb_set(candidate,''{previewHash}'',to_jsonb(finance_document_hash(public_result)),false);
END ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"p_observation text, p_review_revision text","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"s","argumentTypes":"text, text","securityDefiner":false},{"cost":"100","kind":"f","name":"finance_same_observation_projection_v1","rows":"0","binary":null,"config":null,"result":"jsonb","source":"
DECLARE item jsonb;result jsonb:=''[]''::jsonb;
BEGIN
 IF jsonb_typeof(p_snapshot) IS DISTINCT FROM ''object''
  OR jsonb_typeof(p_snapshot->''sourceSnapshots'') IS DISTINCT FROM ''array''
  OR jsonb_array_length(p_snapshot->''sourceSnapshots'')<1
 THEN RAISE EXCEPTION ''Current observation projection unavailable'' USING ERRCODE=''55000'';END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(p_snapshot->''sourceSnapshots'') LOOP
  IF jsonb_typeof(item) IS DISTINCT FROM ''object'' OR finance_supply_id(item->''id'') IS DISTINCT FROM true
   OR item->>''kind'' IS NULL OR item->>''kind'' NOT IN(''card'',''hometax'',''tax_invoice'')
  THEN RAISE EXCEPTION ''Current observation source unavailable'' USING ERRCODE=''55000'';END IF;
  IF item->>''kind''=''card'' THEN
   IF NOT(item ? ''observationState'') OR item->''observationState'' NOT IN(''null''::jsonb,''0''::jsonb,''1''::jsonb)
   THEN RAISE EXCEPTION ''Card observation state unavailable'' USING ERRCODE=''55000'';END IF;
   item:=item-''observationState'';
  END IF;
  result:=result||jsonb_build_array(item);
 END LOOP;
 RETURN jsonb_set(p_snapshot,''{sourceSnapshots}'',result,false);
END ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"p_snapshot jsonb","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"i","argumentTypes":"jsonb","securityDefiner":false},{"cost":"100","kind":"f","name":"finance_same_side","rows":"0","binary":null,"config":null,"result":"jsonb","source":"
DECLARE o finance_document_observations%ROWTYPE; candidate jsonb; issues jsonb:=''[]''; times jsonb:=''[]''; reversals jsonb:=''[]''; merchant jsonb; reversal_merchant jsonb; x jsonb; c jsonb; cr jsonb; orig_review jsonb; rev_review jsonb; diag jsonb; company jsonb; source_hash text; original_hash text; n numeric; counterparty text;
BEGIN
 SELECT * INTO o FROM finance_document_observations WHERE observation_id=p_ref->>''observationId'' AND document_id=p_ref->>''documentId'' AND subject_id=p_draft->>''subjectId'';
 IF NOT FOUND THEN RETURN jsonb_build_object(''issues'',finance_document_issue(''observation_missing'',''정확한 문서 관측을 선택하세요.''),''summary'',NULL,''times'',times);END IF;
 BEGIN PERFORM finance_document_assert_request(o.request_id);EXCEPTION WHEN serialization_failure OR deadlock_detected THEN RAISE;WHEN OTHERS THEN RAISE EXCEPTION ''Stored document proof unavailable'' USING ERRCODE=''55000'';END;
 IF NOT EXISTS(SELECT 1 FROM finance_document_portions WHERE document_id=o.document_id AND portion_id=p_ref->>''portionId'' AND locator=''whole'')
  OR EXISTS(SELECT 1 FROM finance_document_observations WHERE document_id=o.document_id AND version>o.version) THEN issues:=issues||finance_document_issue(''observation_stale'',''최신 문서 전체 관측을 선택하세요.'');END IF;
 candidate:=finance_same_current_candidate_v1(o.observation_id,p_draft->>''reviewRevisionId'');
 IF candidate->>''canRegister'' IS DISTINCT FROM ''true'' OR candidate->''_safeSnapshot'' IS DISTINCT FROM o.safe_snapshot_json OR o.review_revision_id IS DISTINCT FROM p_draft->>''reviewRevisionId''
  OR candidate->>''documentId'' IS DISTINCT FROM o.document_id OR candidate->>''portionId'' IS DISTINCT FROM p_ref->>''portionId''
